import{_ as o,a0 as r,w as p,s as d,I as a,x as e,ao as l,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"8 個基本的 Docker 容器管理命令 | LCTT x X-CMD","titleTemplate":false,"description":"8 個基本的 Docker 容器管理命令 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"8 個基本的 Docker 容器管理命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"8 個基本的 Docker 容器管理命令 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180601 8 basic Docker container management commands","title":"8 個基本的 Docker 容器管理命令","tag":"201806","desc":""},"relativePath":"201806/20180601 8 basic Docker container management commands.md","filePath":"[post].md"}'),c={name:"201806/20180601 8 basic Docker container management commands.md"};function k(u,s,h,b,g,m){const n=r("Link");return p(),d("div",null,[s[27]||(s[27]=a("h1",{id:"_8-個基本的-docker-容器管理命令",tabindex:"-1"},[e("8 個基本的 Docker 容器管理命令 "),a("a",{class:"header-anchor",href:"#_8-個基本的-docker-容器管理命令","aria-label":"Permalink to “8 個基本的 Docker 容器管理命令”"},"​")],-1)),s[28]||(s[28]=a("blockquote",null,[a("p",null,"利用這 8 個命令可以學習 Docker 容器的基本管理方式。這是一個為 Docker 初學者準備的，帶有示範命令輸出的指南。")],-1)),s[29]||(s[29]=a("p",null,[a("img",{src:"https://a4.kerneltalks.com/wp-content/uploads/2018/06/basic-Docker-container-management-commands.png",alt:"Docker 容器管理命令"})],-1)),a("p",null,[s[2]||(s[2]=l("在這篇文章中，我們將帶你學習 8 個基本的 Docker 容器命令，它們操控着 Docker 容器的基本活動，例如 <ruby>運行<rt>run</rt></ruby>、 <ruby>列舉<rt>list</rt></ruby>、 <ruby>停止<rt>stop</rt></ruby>、 查看<ruby>歷史紀錄<rt>logs</rt></ruby>、 <ruby>刪除<rt>delete</rt></ruby> 等等。如果你對 Docker 的概念很陌生，推薦你看看我們的 ",11)),t(n,{href:"https://kerneltalks.com/virtualization/what-is-docker-introduction-guide-to-docker/"},{default:i(()=>[...s[0]||(s[0]=[e("介紹指南",-1)])]),_:1}),s[3]||(s[3]=e("，來了解 Docker 的基本內容以及 ",-1)),t(n,{href:"https://kerneltalks.com/virtualization/how-to-install-docker-in-linux/"},{default:i(()=>[...s[1]||(s[1]=[e("如何",-1)])]),_:1}),s[4]||(s[4]=e(" 在 Linux 上安裝 Docker。 現在讓我們趕快進入要了解的命令：",-1))]),s[30]||(s[30]=a("h3",{id:"如何運行-docker-容器",tabindex:"-1"},[e("如何運行 Docker 容器？ "),a("a",{class:"header-anchor",href:"#如何運行-docker-容器","aria-label":"Permalink to “如何運行 Docker 容器？”"},"​")],-1)),a("p",null,[s[6]||(s[6]=e("眾所周知，Docker 容器只是一個運行於",-1)),s[7]||(s[7]=a("ruby",null,[e("宿主操作系統"),a("rt",null,"host OS")],-1)),s[8]||(s[8]=e("上的應用進程，所以你需要一個鏡像來運行它。Docker 鏡像以進程的方式運行時就叫做 Docker 容器。你可以加載本地 Docker 鏡像，也可以從 Docker Hub 上下載。Docker Hub 是一個提供公有和私有鏡像來進行",-1)),s[9]||(s[9]=a("ruby",null,[e("拉取"),a("rt",null,"pull")],-1)),s[10]||(s[10]=e("操作的集中倉庫。官方的 Docker Hub 位於 ",-1)),t(n,{href:"https://hub.docker.com/"},{default:i(()=>[...s[5]||(s[5]=[e("hub.docker.com",-1)])]),_:1}),s[11]||(s[11]=e("。 當你指示 Docker 引擎運行容器時，它會首先搜索本地鏡像，如果沒有找到，它會從 Docker Hub 上拉取相應的鏡像。",-1))]),s[31]||(s[31]=l(`<p>讓我們運行一個 Apache web 服務器的 Docker 鏡像，比如 httpd 進程。你需要運行 <code>docker container run</code> 命令。舊的命令為 <code>docker run</code>， 但後來 Docker 添加了子命令部分，所以新版本支持下列命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container run -d -p 80:80 httpd</span></span>
<span class="line"><span>Unable to find image &#39;httpd:latest&#39; locally</span></span>
<span class="line"><span>latest: Pulling from library/httpd</span></span>
<span class="line"><span>3d77ce4481b1: Pull complete</span></span>
<span class="line"><span>73674f4d9403: Pull complete</span></span>
<span class="line"><span>d266646f40bd: Pull complete</span></span>
<span class="line"><span>ce7b0dda0c9f: Pull complete</span></span>
<span class="line"><span>01729050d692: Pull complete</span></span>
<span class="line"><span>014246127c67: Pull complete</span></span>
<span class="line"><span>7cd2e04cf570: Pull complete</span></span>
<span class="line"><span>Digest: sha256:f4610c3a1a7da35072870625733fd0384515f7e912c6223d4a48c6eb749a8617</span></span>
<span class="line"><span>Status: Downloaded newer image for httpd:latest</span></span>
<span class="line"><span>c46f2e9e4690f5c28ee7ad508559ceee0160ac3e2b1688a61561ce9f7d99d682</span></span></code></pre></div><p>Docker 的 <code>run</code> 命令將鏡像名作為強制參數，另外還有很多可選參數。常用的參數有：</p><ul><li><code>-d</code>：從當前 shell 脱離容器</li><li><code>-p X:Y</code>：綁定容器的端口 Y 到宿主機的端口 X</li><li><code>--name</code>：命名你的容器。如果未指定，它將被賦予隨機生成的名字</li><li><code>-e</code>：當啓動容器時傳遞環境編輯及其值</li></ul><p>通過以上輸出你可以看到，我們將 <code>httpd</code> 作為鏡像名來運行容器。接着，本地鏡像沒有找到，Docker 引擎從 Docker Hub 拉取了它。注意，它下載了鏡像 <code>httpd:latest</code>， 其中 <code>:</code> 後面跟着版本號。如果你需要運行特定版本的容器，你可以在鏡像名後面註明版本名。如果不提供版本名，Docker 引擎會自動拉取最新的版本。</p><p>輸出的最後一行顯示了你新運行的 httpd 容器的唯一 ID。</p><h3 id="如何列出所有運行中的-docker-容器" tabindex="-1">如何列出所有運行中的 Docker 容器？ <a class="header-anchor" href="#如何列出所有運行中的-docker-容器" aria-label="Permalink to “如何列出所有運行中的 Docker 容器？”">​</a></h3><p>現在，你的容器已經運行起來了，你可能想要確認這一點，或者你想要列出你的機器上運行的所有容器。你可以使用 <code>docker container ls</code> 命令。在舊的 Docker 版本中，對應的命令為 <code>docker ps</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container ls</span></span>
<span class="line"><span>CONTAINER ID        IMAGE               COMMAND              CREATED             STATUS              PORTS                NAMES</span></span>
<span class="line"><span>c46f2e9e4690        httpd               &quot;httpd-foreground&quot;   11 minutes ago      Up 11 minutes       0.0.0.0:80-&gt;80/tcp   cranky_cori</span></span></code></pre></div><p>列出的結果是按列顯示的。每一列的值分別為：</p><ol><li>Container ID ：一開始的幾個字符對應你的容器的唯一 ID</li><li>Image ：你運行容器的鏡像名</li><li>Command ：容器啓動後運行的命令</li><li>Created ：創建時間</li><li>Status ：容器當前狀態</li><li>Ports ：與宿主端口相連接的端口信息</li><li>Names ：容器名（如果你沒有命名你的容器，那麼會隨機創建）</li></ol><h3 id="如何查看-docker-容器的歷史紀錄" tabindex="-1">如何查看 Docker 容器的歷史紀錄？ <a class="header-anchor" href="#如何查看-docker-容器的歷史紀錄" aria-label="Permalink to “如何查看 Docker 容器的歷史紀錄？”">​</a></h3><p>在第一步我們使用了 <code>-d</code> 參數來將容器，在它一開始運行的時候，就從當前的 shell 中脱離出來。在這種情況下，我們不知道容器裏面發生了什麼。所以為了查看容器的歷史紀錄，Docker 提供了 <code>logs</code> 命令。它採用容器名稱或 ID 作為參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container logs cranky_cori</span></span>
<span class="line"><span>AH00558: httpd: Could not reliably determine the server&#39;s fully qualified domain name, using 172.17.0.2. Set the &#39;ServerName&#39; directive globally to suppress this message</span></span>
<span class="line"><span>AH00558: httpd: Could not reliably determine the server&#39;s fully qualified domain name, using 172.17.0.2. Set the &#39;ServerName&#39; directive globally to suppress this message</span></span>
<span class="line"><span>[Thu May 31 18:35:07.301158 2018] [mpm_event:notice] [pid 1:tid 139734285989760] AH00489: Apache/2.4.33 (Unix) configured -- resuming normal operations</span></span>
<span class="line"><span>[Thu May 31 18:35:07.305153 2018] [core:notice] [pid 1:tid 139734285989760] AH00094: Command line: &#39;httpd -D FOREGROUND&#39;</span></span></code></pre></div><p>這裏我使用了容器名稱作為參數。你可以看到在我們的 httpd 容器中與 Apache 相關的歷史紀錄。</p><h3 id="如何確定-docker-容器的進程" tabindex="-1">如何確定 Docker 容器的進程？ <a class="header-anchor" href="#如何確定-docker-容器的進程" aria-label="Permalink to “如何確定 Docker 容器的進程？”">​</a></h3><p>容器是一個使用宿主資源來運行的進程。這樣，你可以在宿主系統的進程表中定位容器的進程。讓我們在宿主系統上確定容器進程。</p><p>Docker 使用著名的 <code>top</code> 命令作為子命令的名稱，來查看容器產生的進程。它採用容器的名稱或 ID 作為參數。在舊版本的 Docker 中，只可運行 <code>docker top</code> 命令。在新版本中，<code>docker top</code> 和 <code>docker container top</code> 命令都可以生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container top  cranky_cori</span></span>
<span class="line"><span>UID                 PID                 PPID                C                   STIME               TTY                 TIME                CMD</span></span>
<span class="line"><span>root                15702               15690               0                   18:35               ?                   00:00:00            httpd -DFOREGROUND</span></span>
<span class="line"><span>bin                 15729               15702               0                   18:35               ?                   00:00:00            httpd -DFOREGROUND</span></span>
<span class="line"><span>bin                 15730               15702               0                   18:35               ?                   00:00:00            httpd -DFOREGROUND</span></span>
<span class="line"><span>bin                 15731               15702               0                   18:35               ?                   00:00:00            httpd -DFOREGROUND</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>root@kerneltalks # ps -ef |grep -i 15702</span></span>
<span class="line"><span>root     15702 15690  0 18:35 ?        00:00:00 httpd -DFOREGROUND</span></span>
<span class="line"><span>bin      15729 15702  0 18:35 ?        00:00:00 httpd -DFOREGROUND</span></span>
<span class="line"><span>bin      15730 15702  0 18:35 ?        00:00:00 httpd -DFOREGROUND</span></span>
<span class="line"><span>bin      15731 15702  0 18:35 ?        00:00:00 httpd -DFOREGROUND</span></span>
<span class="line"><span>root     15993 15957  0 18:59 pts/0    00:00:00 grep --color=auto -i 15702</span></span></code></pre></div><p>在第一個輸出中，列出了容器產生的進程的列表。它包含了所有細節，包括<ruby>用户號<rt>uid</rt></ruby>、<ruby>進程號<rt>pid</rt></ruby>，<ruby>父進程號<rt>ppid</rt></ruby>、開始時間、命令，等等。這裏所有的進程號你都可以在宿主的進程表裏搜索到。這就是我們在第二個命令裏做得。這證明了容器確實是宿主系統中的進程。</p><h3 id="如何停止-docker-容器" tabindex="-1">如何停止 Docker 容器？ <a class="header-anchor" href="#如何停止-docker-容器" aria-label="Permalink to “如何停止 Docker 容器？”">​</a></h3><p>只需要 <code>stop</code> 命令！同樣，它採用容器名稱或 ID 作為參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container stop cranky_cori</span></span>
<span class="line"><span>cranky_cori</span></span></code></pre></div><h3 id="如何列出停止的或不活動的-docker-容器" tabindex="-1">如何列出停止的或不活動的 Docker 容器？ <a class="header-anchor" href="#如何列出停止的或不活動的-docker-容器" aria-label="Permalink to “如何列出停止的或不活動的 Docker 容器？”">​</a></h3><p>現在我們停止了我們的容器，這時如果我們使用 <code>ls</code> 命令，它將不會出現在列表中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container ls</span></span>
<span class="line"><span>CONTAINER ID        IMAGE               COMMAND             CREATED             STATUS              PORTS               NAMES</span></span></code></pre></div><p>所以，在這種情況下，如果想要查看停止的或不活動的容器，你需要在 <code>ls</code> 命令裏同時使用 <code>-a</code> 參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container ls -a</span></span>
<span class="line"><span>CONTAINER ID        IMAGE               COMMAND              CREATED             STATUS                     PORTS               NAMES</span></span>
<span class="line"><span>c46f2e9e4690        httpd               &quot;httpd-foreground&quot;   33 minutes ago      Exited (0) 2 minutes ago                       cranky_cori</span></span></code></pre></div><p>有了 <code>-a</code> 參數，現在我們可以查看已停止的容器。注意這些容器的狀態被標註為 <ruby>已退出<rt>exited</rt></ruby>。既然容器只是一個進程，那麼用“退出”比“停止”更合適！</p><h3 id="如何-重新-啓動-docker-容器" tabindex="-1">如何（重新）啓動 Docker 容器？ <a class="header-anchor" href="#如何-重新-啓動-docker-容器" aria-label="Permalink to “如何（重新）啓動 Docker 容器？”">​</a></h3><p>現在，我們來啓動這個已停止的容器。這和運行一個容器有所區別。當你運行一個容器時，你將啓動一個全新的容器。當你啓動一個容器時，你將開始一個已經停止並保存了當時運行狀態的容器。它將以停止時的狀態重新開始運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks #  docker container start c46f2e9e4690</span></span>
<span class="line"><span>c46f2e9e4690</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>root@kerneltalks # docker container ls -a</span></span>
<span class="line"><span>CONTAINER ID        IMAGE               COMMAND              CREATED             STATUS              PORTS                NAMES</span></span>
<span class="line"><span>c46f2e9e4690        httpd               &quot;httpd-foreground&quot;   35 minutes ago      Up 8 seconds        0.0.0.0:80-&gt;80/tcp   cranky_cori</span></span></code></pre></div><h3 id="如何移除-docker-容器" tabindex="-1">如何移除 Docker 容器？ <a class="header-anchor" href="#如何移除-docker-容器" aria-label="Permalink to “如何移除 Docker 容器？”">​</a></h3><p>我們使用 <code>rm</code> 命令來移除容器。你不可以移除運行中的容器。移除之前需要先停止容器。你可以使用 <code>-f</code> 參數搭配 <code>rm</code> 命令來強制移除容器，但並不推薦這麼做。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container rm cranky_cori</span></span>
<span class="line"><span>cranky_cori</span></span>
<span class="line"><span>root@kerneltalks # docker container ls -a</span></span>
<span class="line"><span>CONTAINER ID        IMAGE               COMMAND             CREATED             STATUS              PORTS               NAMES</span></span></code></pre></div><p>你看，一旦移除了容器，即使再使用 <code>ls -a</code> 命令也查看不到容器了。</p><hr>`,37)),a("p",null,[s[13]||(s[13]=e("via: ",-1)),t(n,{href:"https://kerneltalks.com/virtualization/8-basic-docker-container-management-commands/"},{default:i(()=>[...s[12]||(s[12]=[e("https://kerneltalks.com/virtualization/8-basic-docker-container-management-commands/",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=e("作者：",-1)),t(n,{href:"https://kerneltalks.com"},{default:i(()=>[...s[14]||(s[14]=[e("Shrikant Lavhate",-1)])]),_:1}),s[19]||(s[19]=e(" 選題：",-1)),t(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[15]||(s[15]=[e("lujun9972",-1)])]),_:1}),s[20]||(s[20]=e(" 譯者：",-1)),t(n,{href:"https://github.com/lonaparte"},{default:i(()=>[...s[16]||(s[16]=[e("lonaparte",-1)])]),_:1}),s[21]||(s[21]=e(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[17]||(s[17]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=e("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[22]||(s[22]=[e("LCTT",-1)])]),_:1}),s[25]||(s[25]=e(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:i(()=>[...s[23]||(s[23]=[e("Linux中國",-1)])]),_:1}),s[26]||(s[26]=e(" 榮譽推出",-1))])])}const T=o(c,[["render",k]]);export{y as __pageData,T as default};
